parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "information_extraction_score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 3,
      "description": "1-3. Faithfulness to the ticket."
    },
    "information_extraction_reasoning": {
      "type": "string",
      "description": "Evidence for that score."
    },
    "field_coverage_score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 3,
      "description": "1-3. Did it carry across what an agent needs."
    },
    "field_coverage_reasoning": {
      "type": "string",
      "description": "Evidence for that score."
    }
  },
  "required": [
    "information_extraction_score",
    "information_extraction_reasoning",
    "field_coverage_score",
    "field_coverage_reasoning"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "issue_addressal_score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 3,
      "description": "1-3. Does it address the issue, within policy."
    },
    "issue_addressal_reasoning": {
      "type": "string",
      "description": "Evidence for that score."
    },
    "resolution_clarity_score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 3,
      "description": "1-3. Is the next step unambiguous."
    },
    "resolution_clarity_reasoning": {
      "type": "string",
      "description": "Evidence for that score."
    },
    "overall_score": {
      "type": "integer",
      "minimum": 2,
      "maximum": 6,
      "description": "Sum of the two scores above."
    },
    "overall_reasoning": {
      "type": "string",
      "description": "Is this safe to send as written."
    }
  },
  "required": [
    "issue_addressal_score",
    "issue_addressal_reasoning",
    "resolution_clarity_score",
    "resolution_clarity_reasoning",
    "overall_score",
    "overall_reasoning"
  ],
  "additionalProperties": false
}
